examples.source:
rackdiag {
  16U;
  rack {
    1: UPS [2U];
    3: Router;
    4: Server [4U, color = "#DDEEFF"];
    8: "Disk Array" [description = "storage"];
  }
}

rackdiag {
  rack {
    1: UPS;
    2: PDU;
  }
  rack {
    1: Switch;
    2: Server [width = 2];
  }
}

rackdiag {
  description = "rack A";
  rack {
    1: n0002 [label = "engine"];
    2: n0003 [label = "gearbox", 2U];
  }
}

rackdiag {
  ascending;
  8U;
  rack {
    1: A [2U];
    3: B [color = "#fcc", rotate = 270];
  }
}
